script:
# Find PR On GitHub (flat, no def). Read-only on GitHub.
# Runs after the orchestrator finishes. It looks the pull request up by the Work Item's branch
# and says what the process does next through result["fallback_outcome"]: already_linked,
# pr_found, sandbox_running, github_error, no_pr, handed_back or exhausted. When it finds a pull request the
# process never heard about, it queues the webhook's own events for the Work Item's process.
import re
from datetime import datetime

from frappe.integrations.utils import make_get_request, make_post_request

MAX_ATTEMPTS = 3
MAX_WAIT_CHECKS = 60

if context_doctype != "Work Item" or not context_docname:
    frappe.throw("Find PR On GitHub needs a Work Item as its context.")

fb_attempt = frappe.utils.cint(task_data.get("orch_attempt") or 0)
fb_checks = frappe.utils.cint(task_data.get("fallback_checks") or 0) + 1
# A re-run after a change request only counts when the PR changed after it started (epoch seconds, UTC).
fb_since = float(task_data.get("fallback_since") or 0)

fb_wi = frappe.db.get_value("Work Item", context_docname, ["target_app", "pr_link", "pr_reviewer_user", "git_branch", "title", "orchestrator"], as_dict=True) or {}
# A linked item still asks GitHub while it has no reviewer, so a missed review_requested is replayed.
fb_linked = bool(fb_wi.get("pr_link") and not fb_since)
fb_skip = bool(fb_linked and fb_wi.get("pr_reviewer_user"))
# The orchestrator handed the item to a person (it clears the flag): that ends this loop without a pull request.
fb_handed_back = not fb_wi.get("orchestrator")
fb_repo_url = ""
if fb_wi.get("target_app"):
    fb_repo_url = frappe.db.get_value("GitHub Repository", fb_wi.get("target_app"), "html_url") or ""
fb_m = re.match(r"https?://github\.com/([^/\s]+)/([^/\s]+?)(?:\.git)?/?$", fb_repo_url)

fb_pr = None
fb_prs = []
fb_error = ""
if fb_skip:
    pass
elif not fb_m:
    fb_error = "The Work Item's target app has no GitHub repository on this site."
else:
    fb_owner, fb_repo = fb_m.group(1), fb_m.group(2)
    fb_token = frappe.get_cached_doc("Processa Settings").get_password("github_token", raise_exception=False) or ""
    fb_headers = {"Accept": "application/vnd.github+json", "X-GitHub-Api-Version": "2022-11-28"}
    if fb_token:
        fb_headers["Authorization"] = "Bearer " + fb_token
    try:
        fb_prs = make_get_request(
            "https://api.github.com/repos/" + fb_owner + "/" + fb_repo
            + "/pulls?state=all&per_page=30&head=" + fb_owner + ":" + context_docname,
            headers=fb_headers,
        ) or []
    except Exception as fb_exc:
        fb_prs = []
        fb_error = "GitHub did not answer: " + str(fb_exc)[:300]
    fb_open = [fb_p for fb_p in fb_prs if fb_p.get("state") == "open"]
    fb_merged = [fb_p for fb_p in fb_prs if fb_p.get("merged_at")]
    fb_pr = (fb_open or fb_merged or [None])[0]
    if fb_pr and fb_since:
        fb_updated = datetime.strptime(fb_pr.get("updated_at") or "1970-01-01T00:00:00Z", "%Y-%m-%dT%H:%M:%SZ")
        if (fb_updated - datetime(1970, 1, 1)).total_seconds() < fb_since:
            fb_pr = None

fb_running = False
if not fb_linked:
    fb_running = bool(
        frappe.db.exists(
            "Agent Sandbox Run",
            {
                "state": ["in", ["submitted", "running"]],
                "request_payload": ["like", '%"work_item_id": "' + context_docname + '"%'],
            },
        )
    )

# A branch with commits and no pull request at all gets one now, so a run that forgot to open it still delivers.
fb_finalized = False
fb_base = fb_wi.get("git_branch") or frappe.db.get_value(
    "Agent Sandbox Run", {"work_item": context_docname, "git_branch": ["is", "set"]}, "git_branch", order_by="creation desc"
) or ""
if not (fb_skip or fb_pr or fb_error or fb_running or fb_prs) and fb_m and fb_base:
    try:
        fb_ahead = make_get_request(
            "https://api.github.com/repos/" + fb_owner + "/" + fb_repo + "/compare/"
            + fb_base + "..." + fb_owner + ":" + context_docname,
            headers=fb_headers,
        ).get("ahead_by", 0)
    except Exception:
        fb_ahead = 0  # no such branch on GitHub: nothing was pushed
    if fb_ahead:
        fb_report = frappe.get_all(
            "Comment",
            filters={
                "reference_doctype": "Work Item", "reference_name": context_docname, "comment_type": "Comment",
                "content": ["like", "<b>Orchestrator</b>%"],
            },
            fields=["content"], order_by="creation desc", limit_page_length=1,
        )
        fb_summary = frappe.utils.strip_html(fb_report[0].content.split("<br>", 1)[-1]).strip()[:3000] if fb_report else ""
        fb_failed_tests = frappe.db.exists(
            "Agent Sandbox Run", {"work_item": context_docname, "action": "run_tests", "state": "failed"}
        )
        try:
            fb_pr = make_post_request(
                "https://api.github.com/repos/" + fb_owner + "/" + fb_repo + "/pulls",
                headers=fb_headers,
                json={
                    "title": context_docname + ": " + (fb_wi.get("title") or "")[:72],
                    "head": context_docname,
                    "base": fb_base,
                    "draft": bool(fb_failed_tests or fb_handed_back),
                    "body": (
                        "Work Item: **" + context_docname + "**\n\n"
                        + (("## What the agent reported\n\n" + fb_summary + "\n\n") if fb_summary else "")
                        + "## Status\n\nOpened by Processa because the agent run ended with commits on this branch and no pull request."
                        + (" The agent handed the item back before finishing, so this is a draft with partial work." if fb_handed_back else " The last test run failed, so this is a draft." if fb_failed_tests else " The agent did not report a final test result.")
                    ),
                },
            )
            fb_finalized = True
        except Exception as fb_exc:
            fb_pr = None
            result["finalize_error"] = "Could not open the pull request: " + str(fb_exc)[:300]

fb_waiting = bool(fb_running or fb_error) and fb_checks < MAX_WAIT_CHECKS
if fb_linked:
    fb_outcome = "already_linked"
elif fb_pr:
    fb_outcome = "pr_found"
elif fb_handed_back:
    fb_outcome = "handed_back"
    result["fallback_reason"] = "The work item was handed back to a person, so the loop waits for it to be assigned to the orchestrator again."
elif fb_waiting:
    fb_outcome = "sandbox_running" if fb_running else "github_error"
else:
    fb_attempt += 1
    fb_outcome = "exhausted" if fb_attempt >= MAX_ATTEMPTS else "no_pr"

# Acceptance criteria go on the pull request, and a PR with unmet ones becomes a draft.
if fb_pr and fb_m and fb_outcome == "pr_found":
    try:
        from one_bpmn.one_bpmn.connectors.agent_criteria import publish_criteria

        result.update(publish_criteria(context_docname, fb_owner + "/" + fb_repo, fb_pr, fb_token))
    except Exception as fb_exc:
        result["criteria_error"] = str(fb_exc)[:300]

result["fallback_outcome"] = fb_outcome
result["fallback_error"] = fb_error
result["fallback_finalized"] = int(fb_finalized)
result["fallback_checks"] = fb_checks if fb_waiting else 0
result["orch_attempt"] = fb_attempt
result["reviewer_github_login"] = ""

if fb_outcome == "no_pr":
    # Say on the Work Item why a new attempt starts, so nobody duplicates it to force a retry.
    fb_last = frappe.db.get_value(
        "Agent Sandbox Run", {"work_item": context_docname, "state": ["in", ["failed", "stale", "timed_out"]]},
        ["failure_class", "error_message"], as_dict=True, order_by="creation desc",
    ) or {}
    frappe.get_doc("Work Item", context_docname).add_comment(
        "Comment",
        "<b>Attempt " + str(fb_attempt) + " of " + str(MAX_ATTEMPTS) + "</b><br>No pull request exists for branch "
        + context_docname + ". Running the orchestrator again."
        + (("<br>Last sandbox failure (" + fb_last.get("failure_class") + "): " + frappe.utils.escape_html((fb_last.get("error_message") or "")[:300])) if fb_last.get("failure_class") else ""),
    )

if fb_outcome in ("no_pr", "exhausted"):
    result["fallback_reason"] = (
        "The orchestrator finished and no pull request exists for branch " + context_docname
        + " (attempt " + str(fb_attempt) + " of " + str(MAX_ATTEMPTS) + ")."
    )
    # The hand-back script reads this name.
    result["reason"] = result["fallback_reason"]

if fb_pr:
    # The same keys the GitHub webhook sends, so Set PR Link and Set PR Reviewer need no change.
    fb_reviewers = fb_pr.get("requested_reviewers") or []
    fb_payload = {
        "event_type": "pull_request",
        "action": "opened",
        "pr_url": fb_pr.get("html_url", ""),
        "pr_title": fb_pr.get("title", ""),
        "pr_number": fb_pr.get("number", 0),
        "pr_state": "merged" if fb_pr.get("merged_at") else fb_pr.get("state", ""),
        "pr_merged": bool(fb_pr.get("merged_at")),
        "branch": (fb_pr.get("head") or {}).get("ref", ""),
        "base_branch": (fb_pr.get("base") or {}).get("ref", ""),
        "pr_author": (fb_pr.get("user") or {}).get("login", ""),
        "reviewer_github_login": fb_reviewers[0].get("login", "") if fb_reviewers else "",
    }
    result.update(fb_payload)

    # Events go in order, in one job, after this step commits. A re-run replays nothing, and a linked item already saw opened.
    if not fb_since:
        fb_events = [] if fb_linked else [["github:pull_request:opened", dict(fb_payload)]]
        if fb_reviewers:
            fb_events.append(["github:pull_request:review_requested", dict(fb_payload, action="review_requested")])
        # The latest review of each reviewer decides; a change request nobody answered is replayed.
        fb_states = {}
        try:
            fb_reviews = make_get_request(
                "https://api.github.com/repos/" + fb_owner + "/" + fb_repo + "/pulls/" + str(fb_payload["pr_number"]) + "/reviews?per_page=100",
                headers=fb_headers,
            ) or []
        except Exception as fb_exc:
            fb_reviews = []
            result["fallback_error"] = "GitHub did not answer the reviews: " + str(fb_exc)[:300]
        for fb_rv in fb_reviews:
            if fb_rv.get("state") in ("APPROVED", "CHANGES_REQUESTED", "DISMISSED"):
                fb_states[(fb_rv.get("user") or {}).get("login", "")] = fb_rv["state"]
        fb_changers = [fb_u for fb_u, fb_st in fb_states.items() if fb_st == "CHANGES_REQUESTED"]
        if fb_changers and not fb_payload["pr_merged"] and fb_payload["pr_state"] == "open":
            fb_events.append([
                "github:pull_request_review:changes_requested",
                dict(fb_payload, action="submitted", review_state="changes_requested", reviewer_github_login=fb_changers[0]),
            ])
        if fb_payload["pr_merged"]:
            fb_events.append(["github:pull_request:merged", dict(fb_payload, action="merged")])
        if fb_events:
            frappe.enqueue(
                "frappe_agile.api.github_webhook.replay_events",
                queue="short",
                enqueue_after_commit=True,
                work_item=context_docname,
                events=fb_events,
            )
        result["fallback_replayed"] = len(fb_events)
